from pypdf import PdfReader
r = PdfReader("/online1/ycsc_chenkh/hitici_07/deepseek-harness/attached_files/task_17/JPMORGAN_2022_10K.pdf")

# Search for gross margin related terms across all pages
terms = ["gross margin", "gross profit", "cost of goods", "cost of revenue", "gross margin percentage"]
found = {}
for i, page in enumerate(r.pages):
    txt = page.extract_text() or ""
    low = txt.lower()
    for t in terms:
        if t in low:
            found.setdefault(t, []).append(i+1)

for t in terms:
    print(t, "->", found.get(t, "NOT FOUND"))
